import asyncio
import inspect
from functools import partial, wraps
from fastapi.dependencies.models import Dependant

async def async_func():
    return "async_func"

def sync_func():
    return "sync_func"

def sync_wrapper(f):
    @wraps(f)
    def wrapped(*args, **kwargs):
        return f(*args, **kwargs)
    return wrapped

def async_wrapper(f):
    @wraps(f)
    async def wrapped(*args, **kwargs):
        return await f(*args, **kwargs) if asyncio.iscoroutinefunction(f) else f(*args, **kwargs)
    return wrapped

def test_is_coroutine_callable():
    cases = [
        ("async_func", async_func, True),
        ("sync_func", sync_func, False),
        ("sync_wrapper(async_func)", sync_wrapper(async_func), True),
        ("async_wrapper(sync_func)", async_wrapper(sync_func), True),
        ("partial(async_func)", partial(async_func), True),
        ("partial(sync_wrapper(async_func))", partial(sync_wrapper(async_func)), True),
        ("sync_wrapper(partial(async_func))", sync_wrapper(partial(async_func)), True),
        ("partial(async_wrapper(sync_func))", partial(async_wrapper(sync_func)), True),
        ("async_wrapper(partial(async_func))", async_wrapper(partial(async_func)), True),
