import inspect
from functools import partial
from typing import Any, List
from asyncio import iscoroutinefunction as _iscoroutinefunction

def is_coroutine_function(func: Any) -> bool:
    return _iscoroutinefunction(func)

def get_call_chain(call: Any) -> List[Any]:
    chain = []
    current = call
    while current is not None:
        chain.append(current)
        if isinstance(current, partial):
            current = current.func
        elif hasattr(current, "__wrapped__"):
            current = current.__wrapped__
        else:
            break
    return chain

def is_coroutine_callable(call: Any) -> bool:
    for c in get_call_chain(call):
        if inspect.isroutine(c):
            if is_coroutine_function(c):
                return True
        elif not inspect.isclass(c):
            dunder_call = getattr(c, "__call__", None)
            if is_coroutine_function(dunder_call):
                return True
    return False

def is_gen_callable(call: Any) -> bool:
    for c in get_call_chain(call):
        if inspect.isgeneratorfunction(c):
            return True
        elif not inspect.isclass(c):
            dunder_call = getattr(c, "__call__", None)
            if inspect.isgeneratorfunction(dunder_call):
                return True
    return False

def is_async_gen_callable(call: Any) -> bool:
    for c in get_call_chain(call):
        if inspect.isasyncgenfunction(c):
            return True
        elif not inspect.isclass(c):
            dunder_call = getattr(c, "__call__", None)
            if inspect.isasyncgenfunction(dunder_call):
                return True
    return False

